import * as _backstage_core_plugin_api from '@backstage/core-plugin-api';
import React from 'react';
import * as _backstage_frontend_plugin_api from '@backstage/frontend-plugin-api';

declare const doraMetricsPlugin: _backstage_core_plugin_api.BackstagePlugin<{}, {}, {}>;

declare const DoraScorecard: () => React.JSX.Element;

/**
 * DORA Metrics Frontend Types
 *
 * Note: These types are duplicated in the backend plugin.
 * This is intentional to maintain plugin independence.
 */
interface MetricData {
    current: number;
    change: number;
    target: number;
    tier: string;
    history: number[];
}
interface DoraMetrics {
    deploymentFrequency: MetricData;
    leadTime: MetricData;
    changeFailureRate: MetricData;
    mttr: MetricData;
}
interface DoraResponse {
    metrics: DoraMetrics;
    overallScore: number;
    overallTier: string;
}
interface TargetsPayload {
    deploymentFrequency: number;
    leadTime: number;
    changeFailureRate: number;
    mttr: number;
}

/**
 * API Reference for DORA Metrics
 * This is the contract that defines what operations are available
 */
declare const doraMetricsApiRef: _backstage_frontend_plugin_api.ApiRef<DoraMetricsApi>;
/**
 * DORA Metrics API interface
 */
interface DoraMetricsApi {
    getScorecard(serviceName: string, days: number): Promise<DoraResponse>;
    updateTargets(serviceName: string, targets: TargetsPayload): Promise<void>;
}

export { DoraScorecard, doraMetricsApiRef, doraMetricsPlugin };
export type { DoraMetrics, DoraMetricsApi, DoraResponse, MetricData, TargetsPayload };
